/**
 * GPU-accelerated SDF (Signed Distance Field) generator using mesh BVH.
 *
 * **Overview**
 * Generates a 3D texture containing signed distances from a mesh surface.
 * It uses a BVH (Bounding Volume Hierarchy) acceleration structure to efficiently query the closest point on the mesh for each voxel.
 *
 * **Features**
 * - **Fast Generation**: Uses compute shaders to generate SDFs in parallel.
 * - **BVH Acceleration**: Leverages `three-mesh-bvh` for O(log N) distance queries.
 * - **Dynamic Updates**: Can update the SDF if the mesh deforms (provided the BVH is updated).
 *
 * **Usage**
 * The generated 3D texture can be used for:
 * - **Volume Rendering**: Raymarching clouds, smoke, or fluids.
 * - **Collision Detection**: GPU-based particle collisions.
 * - **VFX**: Attracting/repelling particles from a surface.
 *
 * @example
 * import { GenerateMeshBVHWorker } from 'three-mesh-bvh/worker';
 * import { ComputeSDFGenerator } from '@three-blocks/core';
 *
 * // 1. Generate BVH (async worker recommended)
 * const worker = new GenerateMeshBVHWorker();
 * const bvh = await worker.generate(geometry, { maxLeafTris: 1 });
 *
 * // 2. Create SDF Generator
 * const sdfGen = new ComputeSDFGenerator({
 *   resolution: 64,
 *   margin: 0.2
 * });
 *
 * // 3. Generate SDF Texture
 * await sdfGen.generate(mesh, bvh, renderer);
 * const sdfTexture = sdfGen.sdfTexture;
 *
 * @class ComputeSDFGenerator
 * @short GPU SDF generator that builds a 3D distance texture from a mesh using a BVH.
 * @category Compute
 * @tags WebGPU
 */
export class ComputeSDFGenerator {
    /**
     * Create a new SDF generator.
     *
     * @param {Object} [options] - Configuration options.
     * @param {number} [options.resolution=64] - SDF grid resolution (resolution^3 voxels). Higher is more detailed but slower.
     * @param {number} [options.margin=0.2] - Extra margin around mesh bounds to capture the field.
     * @param {number} [options.threshold=0.0] - Distance threshold (bias) applied to the SDF.
     * @param {THREE.Box3} [options.bounds] - Custom bounds for the SDF volume. Auto-computed from geometry if not provided.
     * @param {THREE.Vector3} [options.workgroupSize=Vector3(4,4,4)] - Compute shader workgroup size. Tweak for performance.
     */
    constructor(options?: {
        resolution?: number;
        margin?: number;
        threshold?: number;
        bounds?: THREE.Box3;
        workgroupSize?: THREE.Vector3;
    });
    /** @type {number} */
    resolution: number;
    /** @type {number} */
    margin: number;
    /** @type {number} */
    threshold: number;
    /** @type {THREE.Box3 | null} */
    customBounds: THREE.Box3 | null;
    /** @type {THREE.Vector3} */
    workgroupSize: THREE.Vector3;
    /** @type {THREE.Storage3DTexture | null} */
    _sdfTexture: THREE.Storage3DTexture | null;
    /** @type {THREE.Matrix4} */
    _boundsMatrix: THREE.Matrix4;
    /** @type {THREE.Matrix4} */
    _inverseBoundsMatrix: THREE.Matrix4;
    /** @type {THREE.Box3} */
    _bounds: THREE.Box3;
    /** @type {THREE.Box3} */
    _geometryBounds: THREE.Box3;
    /** @type {THREE.Matrix4} */
    _meshMatrixWorld: THREE.Matrix4;
    /** @type {*} */
    _computeKernel: any;
    /** @type {boolean} */
    _initialized: boolean;
    /** @private */
    private _uMatrix;
    /** @private */
    private _uDim;
    /** @private */
    private _uThreshold;
    /**
     * Generates SDF texture from mesh and BVH.
     *
     * @param {THREE.BufferGeometry} geometry - Source geometry
     * @param {*} bvh - BVH from three-mesh-bvh (with _roots array)
     * @param {THREE.WebGPURenderer} renderer - WebGPU renderer
     * @returns {Promise<THREE.Storage3DTexture>} Generated SDF texture
     */
    generate(geometry: THREE.BufferGeometry, bvh: any, renderer: THREE.WebGPURenderer): Promise<THREE.Storage3DTexture>;
    _currentBVH: any;
    /**
     * Updates SDF texture with potentially modified mesh/BVH.
     * More efficient than full regeneration if structure hasn't changed.
     *
     * @param {THREE.BufferGeometry} geometry - Source geometry
     * @param {*} bvh - BVH from three-mesh-bvh
     * @param {THREE.WebGPURenderer} renderer - WebGPU renderer
     * @returns {Promise<THREE.Storage3DTexture>} Updated SDF texture
     */
    update(geometry: THREE.BufferGeometry, bvh: any, renderer: THREE.WebGPURenderer): Promise<THREE.Storage3DTexture>;
    /**
     * Computes bounding box with margin.
     * @private
     * @param {THREE.BufferGeometry} geometry
     */
    private _computeBounds;
    /**
     * Computes bounding box from skinned mesh positions.
     * Used for SkinnedMeshBVH where geometry.boundingBox is the bind pose.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @param {*} bvh - SkinnedMeshBVH with mesh reference
     */
    private _computeSkinnedBounds;
    /**
     * Initializes or recreates the Storage3DTexture.
     * @private
     */
    private _initializeTexture;
    /**
     * Builds the compute shader for SDF generation.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @param {*} bvh
     */
    private _buildComputeShader;
    _geomIndex: any;
    _geomPosition: any;
    _bvhNodes: any;
    /**
     * Updates geometry buffers (for dynamic meshes).
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @param {*} bvh
     */
    private _updateGeometryBuffers;
    /**
     * Generates sequential indices for non-indexed geometry.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @returns {Uint32Array}
     */
    private _generateIndices;
    /**
     * Ensures index data is backed by a Uint32Array for GPU consumption.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @returns {Uint32Array}
     */
    private _getIndexArray;
    /**
     * Ensures vertex position data is Float32Array.
     * For SkinnedMeshBVH, extracts transformed positions from the skinned mesh.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @param {*} [bvh] - Optional BVH, used to detect SkinnedMeshBVH
     * @returns {Float32Array}
     */
    private _getPositionArray;
    /**
     * Gets the generated SDF texture.
     * @returns {THREE.Storage3DTexture | null}
     */
    get sdfTexture(): THREE.Storage3DTexture | null;
    /**
     * Gets the bounds transformation matrix (local to world).
     * @returns {THREE.Matrix4}
     */
    get boundsMatrix(): THREE.Matrix4;
    /**
     * Gets the inverse bounds matrix (world to local).
     * @returns {THREE.Matrix4}
     */
    get inverseBoundsMatrix(): THREE.Matrix4;
    /**
     * Gets the computed bounding box (includes margin).
     * @returns {THREE.Box3}
     */
    get bounds(): THREE.Box3;
    /**
     * Gets the tight geometry bounding box (without margin).
     * Useful for focused sampling in ComputeBVHSampler.
     * @returns {THREE.Box3}
     */
    get geometryBounds(): THREE.Box3;
    /**
     * Gets the mesh's world matrix (for skinned meshes).
     * Used by ComputeBVHSampler to transform output to world space.
     * @returns {THREE.Matrix4}
     */
    get meshMatrixWorld(): THREE.Matrix4;
    /**
     * Disposes GPU resources.
     */
    dispose(): void;
}
